// Docs vs registry parity. Every page computes its tool count from
// lib/tools.js, but two files are hand-written: README.md and the
// machine-readable llms.txt. The static `public/llms.txt` said "14 private PDF
// tools" long after the registry had 35 — a crawler repeating the wrong
// catalog is worse than no file at all. llms.txt is now generated by
// `app/llms.txt/route.js`; this check calls the handler directly (no server),
// so the front door and the crawler file are verified against the registry in
// the same run the engines are.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { TOOLS } from '../lib/tools.js';
import { GET as llmsTxt } from '../app/llms.txt/route.js';

let pass = 0, fail = 0;
const check = (name, ok) => { ok ? pass++ : fail++; console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`); };

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const N = TOOLS.length;

// A guard this script can trust: if the registry ever lost most of its entries,
// every check below would happily "pass" against a broken registry.
check(`registry carries the tool set (${N} tools)`, N >= 30);

const readme = fs.readFileSync(path.join(root, 'README.md'), 'utf8');
check('README title states the registry count',
  +(/# AbetPDF — (\d+) private PDF tools/.exec(readme)?.[1] ?? NaN) === N);
check('README build line states the registry count', readme.includes(`all ${N} tool pages`));

check('no static public/llms.txt left to drift out of date',
  !fs.existsSync(path.join(root, 'public', 'llms.txt')));

const llms = await (await llmsTxt()).text();
check('llms.txt summary states the registry count', llms.includes(`${N} private PDF tools`));
check('llms.txt key pages state the registry count', llms.includes(`all ${N} tools`));
const unlinked = TOOLS.filter((t) => !llms.includes(`/${t.slug})`));
check(`llms.txt links every tool${unlinked.length ? ` (missing: ${unlinked.map((t) => t.slug).join(', ')})` : ''}`,
  unlinked.length === 0);

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
